// =====================================================================
// Code Node: "Assinar productOfferV2"   (Mode: Run Once for All Items)
// Monta a query GraphQL productOfferV2 e calcula a assinatura SHA256:
//   Signature = SHA256(AppID + Timestamp + Payload + Secret)
// O "Payload" é exatamente a string JSON enviada no body. Por isso o body
// sai daqui já serializado e o HTTP Request o envia em modo RAW, sem
// re-serializar (qualquer espaço diferente invalida a assinatura).
// Requer: NODE_FUNCTION_ALLOW_BUILTIN=crypto
// =====================================================================
const crypto = require('crypto');

const cfg = $('Config').first().json;

const appId = String(cfg.shopeeAppId || '').trim();
const secret = String(cfg.shopeeSecret || '').trim();
if (!appId || !secret) {
  throw new Error('Shopee App ID / Secret não configurados — preencha em http://localhost:3100 → Configurações.');
}

// sortType: 1=RELEVANCE_DESC 2=ITEM_SOLD_DESC 3=PRICE_DESC 4=PRICE_ASC 5=COMMISSION_DESC
const sortType = parseInt(cfg.sortType, 10) || 5;
const limit = Math.min(Math.max(parseInt(cfg.searchLimit, 10) || 30, 1), 50);

const staticData = $getWorkflowStaticData('global');
const keywords = String(cfg.keywords || '')
  .split(',')
  .map((k) => k.trim())
  .filter(Boolean);

let page;
let keyword = '';
if ($runIndex > 0 && staticData.current) {
  // Nova tentativa (erro temporário da Shopee): repete a MESMA busca, sem avançar o rodízio
  ({ page, keyword } = staticData.current);
} else {
  // Rotaciona a página a cada execução para variar as ofertas
  const maxPage = Math.max(parseInt(cfg.maxPage, 10) || 3, 1);
  staticData.page = ((staticData.page || 0) % maxPage) + 1;
  page = staticData.page;
  // Palavra-chave: aceita lista separada por vírgula e rotaciona entre elas
  if (keywords.length) {
    staticData.kwIndex = ((staticData.kwIndex ?? -1) + 1) % keywords.length;
    keyword = keywords[staticData.kwIndex];
  }
  staticData.current = { page, keyword };
}

// Argumentos GraphQL (JSON.stringify gera string literal válida em GraphQL)
const args = [`sortType: ${sortType}`, `page: ${page}`, `limit: ${limit}`];
if (keyword) args.unshift(`keyword: ${JSON.stringify(keyword)}`);

const query = `query {
  productOfferV2(${args.join(', ')}) {
    nodes {
      itemId
      productName
      productLink
      offerLink
      imageUrl
      priceMin
      priceMax
      priceDiscountRate
      commissionRate
      commission
      sales
      ratingStar
      shopName
      shopId
      periodStartTime
      periodEndTime
    }
    pageInfo {
      page
      limit
      hasNextPage
    }
  }
}`;

const payload = JSON.stringify({ query });
const timestamp = Math.floor(Date.now() / 1000);
const signature = crypto
  .createHash('sha256')
  .update(`${appId}${timestamp}${payload}${secret}`, 'utf8')
  .digest('hex');

return [
  {
    json: {
      url: 'https://open-api.affiliate.shopee.com.br/graphql',
      authorization: `SHA256 Credential=${appId}, Timestamp=${timestamp}, Signature=${signature}`,
      body: payload,
      meta: { keyword: keyword || null, page, sortType, limit, attempt: $runIndex + 1 },
    },
  },
];

// =====================================================================
// Code Node: "Filtrar Ofertas"   (Mode: Run Once for All Items)
// Valida a resposta do productOfferV2, remove produtos já enviados
// (deduplicação persistente via workflow static data), aplica filtros
// de comissão/avaliação e devolve 1 item por produto selecionado.
// =====================================================================
const cfg = $('Config').first().json;
const res = $input.first().json;

if (Array.isArray(res.errors) && res.errors.length) {
  const e = res.errors[0];
  const code = e.extensions?.code ? ` [${e.extensions.code}]` : '';
  throw new Error(`Shopee productOfferV2 falhou${code}: ${e.extensions?.message || e.message}`);
}

const nodes = res?.data?.productOfferV2?.nodes || [];
if (!nodes.length) return [];

const minCommission = parseFloat(cfg.minCommissionRate) || 0; // ex.: 0.08 = 8%
const minRating = parseFloat(cfg.minRating) || 0;             // ex.: 4.5
const maxPosts = parseInt(cfg.maxPostsPerRun, 10) || 3;
const dedupDays = parseInt(cfg.dedupDays, 10) || 7;

// ----- deduplicação (itemId -> epoch do envio) -----
const staticData = $getWorkflowStaticData('global');
staticData.sent = staticData.sent || {};
const now = Date.now();
const ttl = dedupDays * 24 * 60 * 60 * 1000;
for (const [id, ts] of Object.entries(staticData.sent)) {
  if (now - ts > ttl) delete staticData.sent[id];
}

const nowSec = Math.floor(now / 1000);

const selected = nodes
  .filter((p) => p && p.itemId && p.imageUrl && (p.offerLink || p.productLink))
  .filter((p) => !staticData.sent[String(p.itemId)])
  .filter((p) => !p.periodEndTime || Number(p.periodEndTime) === 0 || Number(p.periodEndTime) > nowSec)
  .filter((p) => (parseFloat(p.commissionRate) || 0) >= minCommission)
  .filter((p) => (parseFloat(p.ratingStar) || 0) >= minRating)
  .sort((a, b) => (parseFloat(b.commission) || 0) - (parseFloat(a.commission) || 0))
  .slice(0, maxPosts);

return selected.map((p) => ({
  json: {
    itemId: String(p.itemId),
    productName: p.productName,
    productLink: p.productLink,
    offerLink: p.offerLink,
    imageUrl: p.imageUrl,
    priceMin: parseFloat(p.priceMin) || 0,
    priceMax: parseFloat(p.priceMax) || 0,
    priceDiscountRate: parseInt(p.priceDiscountRate, 10) || 0,
    commissionRate: parseFloat(p.commissionRate) || 0,
    commission: parseFloat(p.commission) || 0,
    sales: parseInt(p.sales, 10) || 0,
    ratingStar: parseFloat(p.ratingStar) || 0,
    shopName: p.shopName,
  },
}));

// =====================================================================
// Code Node: "Assinar generateShortLink"   (Mode: Run Once for All Items)
// Para cada produto, monta a mutation generateShortLink com SubIDs de
// rastreio e assina com SHA256(AppID + Timestamp + Payload + Secret).
// SubIDs: até 5 valores, apenas letras e números.
// =====================================================================
const crypto = require('crypto');

const cfg = $('Config').first().json;
const appId = String(cfg.shopeeAppId || '').trim();
const secret = String(cfg.shopeeSecret || '').trim();

const sanitize = (s) => String(s ?? '').replace(/[^A-Za-z0-9]/g, '').slice(0, 50);

const now = new Date();
const dateTag = now.toISOString().slice(0, 10).replace(/-/g, ''); // AAAAMMDD

return $input.all().map((item) => {
  const p = item.json;
  const originUrl = p.offerLink || p.productLink;

  // sub1=campanha | sub2=canal | sub3=data | sub4=itemId
  const subIds = [cfg.subIdCampaign || 'esteira', 'multicanal', dateTag, p.itemId]
    .map(sanitize)
    .filter(Boolean)
    .slice(0, 5);

  const query = `mutation {
  generateShortLink(input: { originUrl: ${JSON.stringify(originUrl)}, subIds: ${JSON.stringify(subIds)} }) {
    shortLink
  }
}`;

  const payload = JSON.stringify({ query });
  const timestamp = Math.floor(Date.now() / 1000);
  const signature = crypto
    .createHash('sha256')
    .update(`${appId}${timestamp}${payload}${secret}`, 'utf8')
    .digest('hex');

  return {
    json: {
      ...p,
      originUrl,
      subIds,
      url: 'https://open-api.affiliate.shopee.com.br/graphql',
      authorization: `SHA256 Credential=${appId}, Timestamp=${timestamp}, Signature=${signature}`,
      body: payload,
    },
  };
});

// =====================================================================
// Code Node: "Formatar Copy"   (Mode: Run Once for All Items)
// Junta o produto (nó "Assinar generateShortLink") com a resposta da
// mutation (pela mesma posição), formata BRL, monta as legendas do
// Telegram (Markdown) e WhatsApp e extrai a URL direta da imagem.
// Marca o itemId como enviado para não repetir a oferta.
// =====================================================================
const products = $('Assinar generateShortLink').all();
const responses = $input.all();
const staticData = $getWorkflowStaticData('global');
staticData.sent = staticData.sent || {};

const brl = (v) =>
  new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(v) || 0);

// Escape do Markdown legado do Telegram (_ * ` [)
const escTg = (s) => String(s ?? '').replace(/([_*`\[])/g, '\\$1');
// WhatsApp não tem escape: remove caracteres de formatação do título
const cleanWa = (s) => String(s ?? '').replace(/[*_~`]/g, '');

const truncate = (s, n) => (s.length > n ? s.slice(0, n - 1).trim() + '…' : s);

const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

const hooks = [
  '🚨 ACHADO DO DIA NA SHOPEE! 🚨',
  '🔥 PROMOÇÃO RELÂMPAGO! 🔥',
  '💥 PREÇO DE ERRO? CORRE! 💥',
  '⚡ OFERTA IMPERDÍVEL ⚡',
  '🛍️ ACHADINHO SHOPEE 🛍️',
];
const scarcity = [
  '⏳ Estoque limitado — pode acabar a qualquer momento!',
  '⚠️ Preço promocional por tempo limitado!',
  '🏃 Últimas unidades com esse valor!',
  '⌛ Oferta válida enquanto durar o estoque!',
];

// Extrai a URL direta da imagem (Shopee às vezes retorna só o hash do arquivo)
const directImage = (img) => {
  if (!img) return null;
  const s = String(img).trim();
  if (/^https?:\/\//i.test(s)) return s.replace(/^http:/i, 'https:');
  return `https://down-br.img.susercontent.com/file/${s}`;
};

const out = [];

responses.forEach((resItem, i) => {
  const p = products[i]?.json;
  if (!p) return;

  const r = resItem.json;
  if (Array.isArray(r.errors) && r.errors.length) {
    const e = r.errors[0];
    console.log(`generateShortLink falhou para ${p.itemId}: ${e.extensions?.message || e.message}`);
    return; // pula o produto, não interrompe os outros
  }

  const link = r?.data?.generateShortLink?.shortLink || p.offerLink || p.productLink;

  const price = p.priceMin;
  const discount = p.priceDiscountRate;
  const oldPrice = discount > 0 && discount < 100 ? price / (1 - discount / 100) : null;

  const title = truncate(String(p.productName || 'Oferta Shopee').trim(), 120);
  const hook = pick(hooks);
  const urgency = pick(scarcity);
  const rating = p.ratingStar ? `⭐ ${p.ratingStar.toFixed(1)}` : '';
  const sold = p.sales ? `🛒 +${p.sales.toLocaleString('pt-BR')} vendidos` : '';
  const social = [rating, sold].filter(Boolean).join('  |  ');

  // ---------- Telegram (parse_mode: Markdown, máx. 1024 chars) ----------
  const tgLines = [
    `*${escTg(hook)}*`,
    '',
    `📦 *${escTg(title)}*`,
    '',
    oldPrice ? `❌ De: ${escTg(brl(oldPrice))}` : null, // Markdown legado não tem riscado
    `✅ *Por: ${escTg(brl(price))}*${discount ? `  (-${discount}% OFF)` : ''}`,
    social ? escTg(social) : null,
    '',
    escTg(urgency),
    '',
    `👉 [COMPRAR AGORA](${link})`,
  ].filter((l) => l !== null);
  let telegramCaption = tgLines.join('\n');
  if (telegramCaption.length > 1024) telegramCaption = telegramCaption.slice(0, 1020) + '…';

  // ---------- WhatsApp (*negrito*, ~riscado~) ----------
  const waLines = [
    `*${hook}*`,
    '',
    `📦 *${cleanWa(title)}*`,
    '',
    oldPrice ? `❌ De: ~${brl(oldPrice)}~` : null,
    `✅ *Por: ${brl(price)}*${discount ? `  (-${discount}% OFF)` : ''}`,
    social || null,
    '',
    urgency,
    '',
    `👉 *COMPRE AQUI:* ${link}`,
  ].filter((l) => l !== null);
  const whatsappCaption = waLines.join('\n');

  staticData.sent[p.itemId] = Date.now();

  out.push({
    json: {
      itemId: p.itemId,
      productName: p.productName,
      price,
      priceFormatted: brl(price),
      oldPriceFormatted: oldPrice ? brl(oldPrice) : null,
      discount,
      commissionRate: p.commissionRate,
      commission: p.commission,
      estimatedCommission: brl(p.commission),
      affiliateLink: link,
      imageUrl: directImage(p.imageUrl),
      telegramCaption,
      whatsappCaption,
    },
  });
});

return out;

// =====================================================================
// Code Node: "Obs - Resumo da Busca"   (Mode: Run Once for All Items)
// Lê a resposta do productOfferV2 e monta o evento "run" para o painel.
// Fica ACIMA de "Filtrar Ofertas" no canvas: na ordem de execução v1 o
// ramo superior roda primeiro, então a busca é registrada mesmo quando
// "Filtrar Ofertas" lança erro (ex.: Invalid Signature).
// =====================================================================
const res = $input.first().json;
const meta = $('Assinar productOfferV2').first().json.meta || {};

let error = null;
if (Array.isArray(res.errors) && res.errors.length) {
  const e = res.errors[0];
  const code = e.extensions?.code ? `[${e.extensions.code}] ` : '';
  error = `${code}${e.extensions?.message || e.message || 'Erro desconhecido'}`;
}

return [
  {
    json: {
      type: 'run',
      executionId: String($execution.id),
      mode: $execution.mode,
      keyword: meta.keyword,
      page: meta.page,
      sortType: meta.sortType,
      found: (res?.data?.productOfferV2?.nodes || []).length,
      error,
    },
  },
];

// =====================================================================
// Code Node: "Obs - Normalizar Entregas"   (Mode: Run Once for All Items)
// Recebe a saída de "Telegram - sendPhoto" OU "WhatsApp - Evolution
// sendMedia" (executa uma vez para cada ramo) e monta um evento
// "deliveries" com sucesso/erro de cada oferta.
// Os nós de envio usam On Error = Continue, então falhas chegam aqui
// como itens com o campo "error" em vez de interromper o workflow.
// =====================================================================
const prev = typeof $prevNode !== 'undefined' && $prevNode ? $prevNode.name : '';
const responses = $input.all();
const offers = $('Formatar Copy').all();

// Canal pelo nó anterior; se indisponível, pelo formato da resposta
let channel = /telegram/i.test(prev) ? 'telegram' : /whatsapp|evolution/i.test(prev) ? 'whatsapp' : null;
if (!channel) {
  const sample = responses.find((r) => r.json && !r.json.error)?.json || {};
  channel = 'ok' in sample || 'result' in sample ? 'telegram' : 'whatsapp';
}

const errorText = (r) => {
  if (r.error) {
    if (typeof r.error === 'string') return r.error;
    return r.error.description || r.error.message || JSON.stringify(r.error).slice(0, 500);
  }
  if (channel === 'telegram' && r.ok === false) return r.description || 'Telegram retornou ok=false';
  if (channel === 'whatsapp' && !r.key) return r.message ? JSON.stringify(r.message).slice(0, 500) : 'Evolution API não retornou key';
  return null;
};

const events = responses.map((item, i) => {
  const r = item.json || {};
  const o = offers[i]?.json || {};
  const error = errorText(r);
  return {
    channel,
    itemId: o.itemId,
    productName: o.productName,
    price: o.price,
    commissionRate: o.commissionRate,
    commission: o.commission,
    affiliateLink: o.affiliateLink,
    imageUrl: o.imageUrl,
    success: !error,
    error,
    messageId: channel === 'telegram' ? r.result?.message_id : r.key?.id,
  };
});

return [{ json: { type: 'deliveries', executionId: String($execution.id), events } }];
